rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 400 or not isinstance(responseBody, dict):
        return False
    if not (isinstance(responseBody.get('code'), int) and (not isinstance(responseBody.get('code'), bool))) or responseBody['code'] != 40001:
        return False
    if not all((key in responseBody for key in ('code', 'message', 'data', 'requestId'))):
        return False
    if not isinstance(responseBody['requestId'], str) or not responseBody['requestId'].strip():
        return False
    message = responseBody.get('message')
    if not isinstance(message, str) or not message.strip():
        return False
    details = (message + ' ' + str(responseBody.get('data'))).lower()
    return any((field in details for field in ('identityvalue', 'email', '邮箱')))
